const today = new Date();
today.setHours(0, 0, 0, 0);

return $input.all().map(item => {
  const row = item.json;
  const raw = (row['Data Scadenza'] || '').trim();
  const idScadenza = (row['ID Scadenza'] || '').trim();
  const email = (row['Email'] || '').trim();

  // Validate required fields
  if (!idScadenza) {
    return { json: { ...row, reminderType: 'invalid', _errorMsg: 'ID Scadenza mancante' } };
  }
  if (!email || !email.includes('@')) {
    return { json: { ...row, reminderType: 'invalid', _errorMsg: 'Email mancante o non valida' } };
  }

  // Parse date: DD/MM/YYYY or YYYY-MM-DD
  let scadenza;
  if (/^\d{2}\/\d{2}\/\d{4}$/.test(raw)) {
    const [d, m, y] = raw.split('/');
    scadenza = new Date(`${y}-${m}-${d}`);
  } else if (raw) {
    scadenza = new Date(raw);
  }

  if (!raw || !scadenza || isNaN(scadenza.getTime())) {
    return { json: { ...row, reminderType: 'invalid', _errorMsg: `Data non valida: "${raw}"` } };
  }

  const daysUntil = Math.ceil((scadenza - today) / 86400000);

  const sent7 = (row['Reminder 7gg Inviato'] || '').trim().toUpperCase() === 'SI';
  const sent2 = (row['Reminder 2gg Inviato'] || '').trim().toUpperCase() === 'SI';

  let reminderType = 'skip';
  if (daysUntil >= 0 && daysUntil <= 2 && !sent2) {
    reminderType = '2gg';
  } else if (daysUntil >= 3 && daysUntil <= 7 && !sent7) {
    reminderType = '7gg';
  }

  return { json: { ...row, 'ID Scadenza': idScadenza, daysUntil, reminderType } };
});

const cfg = $('Workflow Config').first().json;
const test = cfg.TEST_MODE === 'true';
const studioEmail = cfg.STUDIO_EMAIL;
const studioName = cfg.STUDIO_NAME || 'Il tuo studio';

// Group rows by Email
const grouped = {};
for (const item of $input.all()) {
  const r = item.json;
  const key = r.Email;
  if (!grouped[key]) grouped[key] = { email: r.Email, cliente: r.Cliente, rows: [] };
  grouped[key].rows.push(r);
}

return Object.values(grouped).map(g => {
  const to = test ? studioEmail : g.email;
  const deadlines = g.rows.map(r =>
    `<tr><td style="padding:8px 12px;border:1px solid #e0e0e0;">${r['Tipo Scadenza']}</td>` +
    `<td style="padding:8px 12px;border:1px solid #e0e0e0;font-weight:600;color:#c62828;">${r['Data Scadenza']}</td>` +
    `<td style="padding:8px 12px;border:1px solid #e0e0e0;">${r.daysUntil} giorni</td></tr>`
  ).join('');
  const subject = g.rows.length > 1
    ? `Promemoria 7 giorni: ${g.rows.length} scadenze — ${studioName}`
    : `Promemoria 7 giorni: ${g.rows[0]['Tipo Scadenza']} il ${g.rows[0]['Data Scadenza']}`;
  const body = `<!DOCTYPE html><html><body style="font-family:Arial,sans-serif;color:#333;max-width:600px;margin:0 auto;padding:20px;"><div style="background:#e3f2fd;border-left:4px solid #1565c0;padding:16px 20px;margin-bottom:20px;border-radius:0 4px 4px 0;"><h2 style="color:#0d47a1;margin:0 0 4px;font-size:18px;">&#128197; Promemoria Scadenze — 7 giorni</h2><p style="margin:0;font-size:12px;color:#555;">Notifica automatica</p></div><p style="font-size:15px;">Gentile <strong>${g.cliente}</strong>,</p><p style="font-size:15px;">Le ricordiamo le seguenti scadenze fiscali nei prossimi 7 giorni:</p><table style="width:100%;border-collapse:collapse;font-size:14px;margin:16px 0;"><tr style="background:#f5f5f5;"><th style="padding:8px 12px;text-align:left;border:1px solid #e0e0e0;">Tipo</th><th style="padding:8px 12px;text-align:left;border:1px solid #e0e0e0;">Scadenza</th><th style="padding:8px 12px;text-align:left;border:1px solid #e0e0e0;">Giorni</th></tr>${deadlines}</table><p style="font-size:15px;">La preghiamo di contattarci per fornire la documentazione entro i termini previsti.</p><div style="margin-top:24px;padding-top:12px;border-top:1px solid #eee;"><p style="margin:0;font-size:15px;">Cordiali saluti,</p><p style="margin:4px 0 0;font-size:15px;font-weight:600;">${studioName}</p></div>${test ? '<p style="color:red;font-size:11px;margin-top:12px;">[TEST MODE — destinatario originale: ' + g.email + ']</p>' : ''}</body></html>`;
  return { json: { emailTo: to, emailSubject: subject, emailBody: body, rows: g.rows } };
});

const now = new Date().toISOString();
const out = [];
for (const item of $input.all()) {
  for (const row of (item.json.rows || [])) {
    out.push({ json: {
      'ID Scadenza': row['ID Scadenza'],
      'Reminder 7gg Inviato': 'SI',
      'Data Invio 7gg': now,
      'Stato': 'promemoria-7gg'
    }});
  }
}
return out;

